// Package domain defines GoStore's core types and rules.
// It has no knowledge of HTTP or the filesystem.
package domain

import "time"

// Bucket is a named container for objects.
type Bucket struct {
	Name      string
	CreatedAt time.Time
}

// Object describes a stored object. The data lives in the blob named by BlobID.
// The blob ID is generated by the server and never derived from the key.
type Object struct {
	Bucket      string
	Key         string
	BlobID      string
	Size        int64
	ETag        string
	SHA256      string
	ContentType string
	Metadata    map[string]string
	ModifiedAt  time.Time
}

// Upload is a multipart upload that has not been completed or aborted.
type Upload struct {
	ID           string
	Bucket       string
	Key          string
	ContentType  string
	Metadata     map[string]string
	CreatedAt    time.Time
	LastActiveAt time.Time
}

// Part is one uploaded piece of a multipart upload.
type Part struct {
	UploadID   string
	Number     int
	BlobID     string
	Size       int64
	ETag       string
	ModifiedAt time.Time
}

// Default limits for listing and multipart uploads.
const (
	DefaultMaxKeys                = 1000
	DefaultMaxPartSize            = int64(1 << 30) // 1 GiB
	DefaultMaxMultipartObjectSize = int64(5 << 30) // 5 GiB
	DefaultMinPartSize            = int64(5 << 20) // 5 MiB
	DefaultMaxUploadParts         = 10000
	DefaultUploadExpiry           = 24 * time.Hour
)

// CompletedPart identifies one part submitted to CompleteMultipartUpload.
type CompletedPart struct {
	Number int
	ETag   string
}

// CompletedUpload caches the result of completing an upload for idempotent retries.
type CompletedUpload struct {
	UploadID    string
	Bucket      string
	Key         string
	ETag        string
	CompletedAt time.Time
}

// ListPartsOptions controls a multipart upload part listing.
type ListPartsOptions struct {
	Bucket           string
	Key              string
	UploadID         string
	PartNumberMarker int
	MaxParts         int
}

// ListPartsResult is one page of uploaded parts.
type ListPartsResult struct {
	Upload               Upload
	Parts                []Part
	PartNumberMarker     int
	NextPartNumberMarker int
	MaxParts             int
	IsTruncated          bool
}

// ListOptions controls a bucket object listing.
type ListOptions struct {
	Bucket            string
	Prefix            string
	Delimiter         string
	MaxKeys           int
	ContinuationToken string
	StartAfter        string
}

// ListResult is one page of objects and common prefixes from a bucket listing.
type ListResult struct {
	Objects               []Object
	CommonPrefixes        []string
	IsTruncated           bool
	NextContinuationToken string
}
